window.KH_SURA(30, {"sura": "الروم", "n": 30, "ayat": {"1": "الم", "2": "غُلِبَتِ الرُّومُ", "3": "فِي أَدْنَى الْأَرْضِ وَهُمْ مِنْ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ", "4": "فِي بِضْعِ سِنِينَ لِلَّهِ الْأَمْرُ مِنْ قَبْلُ وَمِنْ بَعْدُ وَيَوْمَئِذٍ يَفْرَحُ الْمُؤْمِنُونَ", "5": "بِنَصْرِ اللَّهِ يَنْصُرُ مَنْ يَشَاءُ وَهُوَ الْعَزِيزُ الرَّحِيمُ", "6": "وَعْدَ اللَّهِ لَا يُخْلِفُ اللَّهُ وَعْدَهُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ", "7": "يَعْلَمُونَ ظَاهِرًا مِنَ الْحَيَاةِ الدُّنْيَا وَهُمْ عَنِ الْآخِرَةِ هُمْ غَافِلُونَ", "8": "أَوَلَمْ يَتَفَكَّرُوا فِي أَنْفُسِهِمْ مَا خَلَقَ اللَّهُ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُسَمًّى وَإِنَّ كَثِيرًا مِنَ النَّاسِ بِلِقَاءِ رَبِّهِمْ لَكَافِرُونَ", "9": "أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِنْ قَبْلِهِمْ كَانُوا أَشَدَّ مِنْهُمْ قُوَّةً وَأَثَارُوا الْأَرْضَ وَعَمَرُوهَا أَكْثَرَ مِمَّا عَمَرُوهَا وَجَاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِنْ كَانُوا أَنْفُسَهُمْ يَظْلِمُونَ", "10": "ثُمَّ كَانَ عَاقِبَةَ الَّذِينَ أَسَاءُوا السُّوأَى أَنْ كَذَّبُوا بِآيَاتِ اللَّهِ وَكَانُوا بِهَا يَسْتَهْزِئُونَ", "11": "اللَّهُ يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ ثُمَّ إِلَيْهِ تُرْجَعُونَ", "12": "وَيَوْمَ تَقُومُ السَّاعَةُ يُبْلِسُ الْمُجْرِمُونَ", "13": "وَلَمْ يَكُنْ لَهُمْ مِنْ شُرَكَائِهِمْ شُفَعَاءُ وَكَانُوا بِشُرَكَائِهِمْ كَافِرِينَ", "14": "وَيَوْمَ تَقُومُ السَّاعَةُ يَوْمَئِذٍ يَتَفَرَّقُونَ", "15": "فَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَهُمْ فِي رَوْضَةٍ يُحْبَرُونَ", "16": "وَأَمَّا الَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا وَلِقَاءِ الْآخِرَةِ فَأُولَئِكَ فِي الْعَذَابِ مُحْضَرُونَ", "17": "فَسُبْحَانَ اللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ", "18": "وَلَهُ الْحَمْدُ فِي السَّمَاوَاتِ وَالْأَرْضِ وَعَشِيًّا وَحِينَ تُظْهِرُونَ", "19": "يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَيُحْيِ الْأَرْضَ بَعْدَ مَوْتِهَا وَكَذَلِكَ تُخْرَجُونَ", "20": "وَمِنْ آيَاتِهِ أَنْ خَلَقَكُمْ مِنْ تُرَابٍ ثُمَّ إِذَا أَنْتُمْ بَشَرٌ تَنْتَشِرُونَ", "21": "وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا لِتَسْكُنُوا إِلَيْهَا وَجَعَلَ بَيْنَكُمْ مَوَدَّةً وَرَحْمَةً إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ", "22": "وَمِنْ آيَاتِهِ خَلْقُ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافُ أَلْسِنَتِكُمْ وَأَلْوَانِكُمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِلْعَالِمِينَ", "23": "وَمِنْ آيَاتِهِ مَنَامُكُمْ بِاللَّيْلِ وَالنَّهَارِ وَابْتِغَاؤُكُمْ مِنْ فَضْلِهِ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَسْمَعُونَ", "24": "وَمِنْ آيَاتِهِ يُرِيكُمُ الْبَرْقَ خَوْفًا وَطَمَعًا وَيُنَزِّلُ مِنَ السَّمَاءِ مَاءً فَيُحْيِي بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَعْقِلُونَ", "25": "وَمِنْ آيَاتِهِ أَنْ تَقُومَ السَّمَاءُ وَالْأَرْضُ بِأَمْرِهِ ثُمَّ إِذَا دَعَاكُمْ دَعْوَةً مِنَ الْأَرْضِ إِذَا أَنْتُمْ تَخْرُجُونَ", "26": "وَلَهُ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ كُلٌّ لَهُ قَانِتُونَ", "27": "وَهُوَ الَّذِي يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ وَهُوَ أَهْوَنُ عَلَيْهِ وَلَهُ الْمَثَلُ الْأَعْلَى فِي السَّمَاوَاتِ وَالْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ", "28": "ضَرَبَ لَكُمْ مَثَلًا مِنْ أَنْفُسِكُمْ هَلْ لَكُمْ مِنْ مَا مَلَكَتْ أَيْمَانُكُمْ مِنْ شُرَكَاءَ فِي مَا رَزَقْنَاكُمْ فَأَنْتُمْ فِيهِ سَوَاءٌ تَخَافُونَهُمْ كَخِيفَتِكُمْ أَنْفُسَكُمْ كَذَلِكَ نُفَصِّلُ الْآيَاتِ لِقَوْمٍ يَعْقِلُونَ", "29": "بَلِ اتَّبَعَ الَّذِينَ ظَلَمُوا أَهْوَاءَهُمْ بِغَيْرِ عِلْمٍ فَمَنْ يَهْدِي مَنْ أَضَلَّ اللَّهُ وَمَا لَهُمْ مِنْ نَاصِرِينَ", "30": "فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا فِطْرَتَ اللَّهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ اللَّهِ ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ", "31": "مُنِيبِينَ إِلَيْهِ وَاتَّقُوهُ وَأَقِيمُوا الصَّلَاةَ وَلَا تَكُونُوا مِنَ الْمُشْرِكِينَ", "32": "مِنَ الَّذِينَ فَرَّقُوا دِينَهُمْ وَكَانُوا شِيَعًا كُلُّ حِزْبٍ بِمَا لَدَيْهِمْ فَرِحُونَ", "33": "وَإِذَا مَسَّ النَّاسَ ضُرٌّ دَعَوْا رَبَّهُمْ مُنِيبِينَ إِلَيْهِ ثُمَّ إِذَا أَذَاقَهُمْ مِنْهُ رَحْمَةً إِذَا فَرِيقٌ مِنْهُمْ بِرَبِّهِمْ يُشْرِكُونَ", "34": "لِيَكْفُرُوا بِمَا آتَيْنَاهُمْ فَتَمَتَّعُوا فَسَوْفَ تَعْلَمُونَ", "35": "أَمْ أَنْزَلْنَا عَلَيْهِمْ سُلْطَانًا فَهُوَ يَتَكَلَّمُ بِمَا كَانُوا بِهِ يُشْرِكُونَ", "36": "وَإِذَا أَذَقْنَا النَّاسَ رَحْمَةً فَرِحُوا بِهَا وَإِنْ تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ إِذَا هُمْ يَقْنَطُونَ", "37": "أَوَلَمْ يَرَوْا أَنَّ اللَّهَ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ وَيَقْدِرُ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يُؤْمِنُونَ", "38": "فَآتِ ذَا الْقُرْبَى حَقَّهُ وَالْمِسْكِينَ وَابْنَ السَّبِيلِ ذَلِكَ خَيْرٌ لِلَّذِينَ يُرِيدُونَ وَجْهَ اللَّهِ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ", "39": "وَمَا آتَيْتُمْ مِنْ رِبًا لِيَرْبُوَ فِي أَمْوَالِ النَّاسِ فَلَا يَرْبُو عِنْدَ اللَّهِ وَمَا آتَيْتُمْ مِنْ زَكَاةٍ تُرِيدُونَ وَجْهَ اللَّهِ فَأُولَئِكَ هُمُ الْمُضْعِفُونَ", "40": "اللَّهُ الَّذِي خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ هَلْ مِنْ شُرَكَائِكُمْ مَنْ يَفْعَلُ مِنْ ذَلِكُمْ مِنْ شَيْءٍ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ", "41": "ظَهَرَ الْفَسَادُ فِي الْبَرِّ وَالْبَحْرِ بِمَا كَسَبَتْ أَيْدِي النَّاسِ لِيُذِيقَهُمْ بَعْضَ الَّذِي عَمِلُوا لَعَلَّهُمْ يَرْجِعُونَ", "42": "قُلْ سِيرُوا فِي الْأَرْضِ فَانْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِنْ قَبْلُ كَانَ أَكْثَرُهُمْ مُشْرِكِينَ", "43": "فَأَقِمْ وَجْهَكَ لِلدِّينِ الْقَيِّمِ مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لَا مَرَدَّ لَهُ مِنَ اللَّهِ يَوْمَئِذٍ يَصَّدَّعُونَ", "44": "مَنْ كَفَرَ فَعَلَيْهِ كُفْرُهُ وَمَنْ عَمِلَ صَالِحًا فَلِأَنْفُسِهِمْ يَمْهَدُونَ", "45": "لِيَجْزِيَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِنْ فَضْلِهِ إِنَّهُ لَا يُحِبُّ الْكَافِرِينَ", "46": "وَمِنْ آيَاتِهِ أَنْ يُرْسِلَ الرِّيَاحَ مُبَشِّرَاتٍ وَلِيُذِيقَكُمْ مِنْ رَحْمَتِهِ وَلِتَجْرِيَ الْفُلْكُ بِأَمْرِهِ وَلِتَبْتَغُوا مِنْ فَضْلِهِ وَلَعَلَّكُمْ تَشْكُرُونَ", "47": "وَلَقَدْ أَرْسَلْنَا مِنْ قَبْلِكَ رُسُلًا إِلَى قَوْمِهِمْ فَجَاءُوهُمْ بِالْبَيِّنَاتِ فَانْتَقَمْنَا مِنَ الَّذِينَ أَجْرَمُوا وَكَانَ حَقًّا عَلَيْنَا نَصْرُ الْمُؤْمِنِينَ", "48": "اللَّهُ الَّذِي يُرْسِلُ الرِّيَاحَ فَتُثِيرُ سَحَابًا فَيَبْسُطُهُ فِي السَّمَاءِ كَيْفَ يَشَاءُ وَيَجْعَلُهُ كِسَفًا فَتَرَى الْوَدْقَ يَخْرُجُ مِنْ خِلَالِهِ فَإِذَا أَصَابَ بِهِ مَنْ يَشَاءُ مِنْ عِبَادِهِ إِذَا هُمْ يَسْتَبْشِرُونَ", "49": "وَإِنْ كَانُوا مِنْ قَبْلِ أَنْ يُنَزَّلَ عَلَيْهِمْ مِنْ قَبْلِهِ لَمُبْلِسِينَ", "50": "فَانْظُرْ إِلَى آثَارِ رَحْمَتِ اللَّهِ كَيْفَ يُحْيِ الْأَرْضَ بَعْدَ مَوْتِهَا إِنَّ ذَلِكَ لَمُحْيِ الْمَوْتَى وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", "51": "وَلَئِنْ أَرْسَلْنَا رِيحًا فَرَأَوْهُ مُصْفَرًّا لَظَلُّوا مِنْ بَعْدِهِ يَكْفُرُونَ", "52": "فَإِنَّكَ لَا تُسْمِعُ الْمَوْتَى وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ", "53": "وَمَا أَنْتَ بِهَادِ الْعُمْيِ عَنْ ضَلَالَتِهِمْ إِنْ تُسْمِعُ إِلَّا مَنْ يُؤْمِنُ بِآيَاتِنَا فَهُمْ مُسْلِمُونَ", "54": "اللَّهُ الَّذِي خَلَقَكُمْ مِنْ ضَعْفٍ ثُمَّ جَعَلَ مِنْ بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِنْ بَعْدِ قُوَّةٍ ضَعْفًا وَشَيْبَةً يَخْلُقُ مَا يَشَاءُ وَهُوَ الْعَلِيمُ الْقَدِيرُ", "55": "وَيَوْمَ تَقُومُ السَّاعَةُ يُقْسِمُ الْمُجْرِمُونَ مَا لَبِثُوا غَيْرَ سَاعَةٍ كَذَلِكَ كَانُوا يُؤْفَكُونَ", "56": "وَقَالَ الَّذِينَ أُوتُوا الْعِلْمَ وَالْإِيمَانَ لَقَدْ لَبِثْتُمْ فِي كِتَابِ اللَّهِ إِلَى يَوْمِ الْبَعْثِ فَهَذَا يَوْمُ الْبَعْثِ وَلَكِنَّكُمْ كُنْتُمْ لَا تَعْلَمُونَ", "57": "فَيَوْمَئِذٍ لَا يَنْفَعُ الَّذِينَ ظَلَمُوا مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَبُونَ", "58": "وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِنْ كُلِّ مَثَلٍ وَلَئِنْ جِئْتَهُمْ بِآيَةٍ لَيَقُولَنَّ الَّذِينَ كَفَرُوا إِنْ أَنْتُمْ إِلَّا مُبْطِلُونَ", "59": "كَذَلِكَ يَطْبَعُ اللَّهُ عَلَى قُلُوبِ الَّذِينَ لَا يَعْلَمُونَ", "60": "فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَا يَسْتَخِفَّنَّكَ الَّذِينَ لَا يُوقِنُونَ"}, "units": [{"aya": 0, "title": "قراءة قوله تعالى: {غلبت الروم}", "mawsua": {"taliq": 5081, "masala": "قراءة قوله تعالى: {غلبت الروم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "{غلبت} بضم الغين وكسر اللام", "ashab": "", "athar": []}, {"n": 2, "t": "(غلبت) بفتح الغين واللام", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5081, "mi": 1, "aya": 0, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 5", "qawl": "", "nass": "وتأويل ذلك: أن الذي طرأ يوم بدر إنما كان أن الروم غلبت، فعز ذلك على كفار قريش، وسر المسلمون، فبشر الله تعالى عباده بأنهم سيغلبون أيضا في بضع سنين. ذكر هذا التأويل أبو حاتم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 4, "title": "هذه الآية", "mawsua": {"taliq": 5088, "masala": "هذه الآية", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون عطفا على القبل والبعد", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون الكلام قد تم في قوله: {بعد}، ثم استأنف عطف جملة أخبر فيها أن يوم غلبة الروم الفرس يفرح المؤمنين بنصر الله", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5088, "mi": 1, "aya": 4, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 8", "qawl": "", "nass": "أن يكون عطفا على القبل والبعد", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 4, "title": "السنة التي غلبت فيها الروم أهل فارس", "mawsua": {"taliq": 5089, "masala": "السنة التي غلبت فيها الروم أهل فارس", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "يوم وقعة بدر", "ashab": "", "athar": []}, {"n": 2, "t": "عام الحديبية", "ashab": "", "athar": []}, {"n": 3, "t": "أن يشار فيه إلى فرح المسلمين بنصر الله تعالى إياهم في أن صدق ما قال نبيهم عليه الصلاة والسلام في أن الروم ستغلب فارس، فإن هذا ضرب من النصر عظيم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5089, "mi": 1, "aya": 4, "alam": "ابن كثير", "fil": "نقل", "kind": "نقل", "ref": "11/ 13 - 14", "qawl": "الثاني", "nass": "بأن قيصر كان قد نذر لئن أظفره الله بكسرى ليمشين من حمص إلى إيليا -وهو بيت المقدس- شكرا لله عز وجل، ففعل، فلما بلغ بيت المقدس لم يخرج منها حتى وافاه كتاب رسول الله صلى الله عليه وسلم الذي بعثه مع دحية بن خليفة، فأعطاه دحية لعظيم بصرى، فدفعه عظيم بصرى إلى قيصر. فلما وصل إليه سأل: من بالشام من عرب الحجاز؟ فأحضر له أبو سفيان صخر بن حرب الأموي في جماعة من كفار قريش كانوا في غزة، فجيء بهم إليه، فجلسوا بين يديه، فقال: أيكم أقرب نسبا بهذا الرجل الذي يزعم أنه نبي؟ فقال أبو سفيان: أنا. فقال لأصحابه -وأجلسهم خلفه-: إني سائل هذا عن هذا الرجل، فإن كذب فكذبوه. فقال أبو سفيان: فوالله، لولا أن يأثروا علي الكذب لكذبت. فسأله هرقل عن نسبه وصفته، فكان فيما سأله أن قال: فهل يغدر؟ قال: قلت: لا، ونحن منه في مدة لا ندري ما هو صانع فيها. يعني بذلك: الهدنة التي كانت قد وقعت بين رسول الله صلى الله عليه وسلم وكفار قريش يوم الحديبية على وضع الحرب بينهم عشر سنين، فاستدلوا بهذا على أن نصر الروم على فارس كان عام الحديب", "qawaid": [], "tabi": ""}, {"taliq": 5089, "mi": 1, "aya": 4, "alam": "ابن تيمية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 118", "qawl": "", "nass": "وهذا هو الصحيح", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 5089, "mi": 1, "aya": 4, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 8 - 9", "qawl": "", "nass": "أن يشار فيه إلى نصر الروم على فارس", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن تيمية", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن تيمية": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 7, "title": "تأويل: ﴿يعلمون ظاهرا من الحياة الدنيا وهم عن الآخرة هم غافلون﴾", "tabari": {"page": "18/463", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: يعلم هؤلاء المكذبون بحقيقة خبر الله أن الروم ستغلب فارس- ﴿ظاهرا﴾ من أمر حياتهم الدنيا وتدبير معايشهم فيها، وما يصلحهم، رهم عن أمر آخرتهم، وما لهم فيه النجاة من عقاب الله هنالك غافلون، لا يفكرون فيه.", "taqdim": 1, "n_athar": 15, "qailun": [["ابن عباس", "صحابي"], ["عكرمة", "تابعي"], ["عكرمة فى", "تابعي"], ["إبراهيم", "تابعي"], ["قتادة", "تابعي"], ["أبى العالية", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [60385, 60386, 60387, 60389, 60390, 60395]}, {"n": 2, "t": "ثنا يعقوب القمي، عن جعفر، عن سعيد في قوله: ﴿يعلمون ظاهرا من الحياة الدنيا﴾. قال: تسترق الشياطين السمع، فيسمعون الكلمة التي قد نزلت، ينبغى لها أن تكون في الأرض. قال: ويرمون بالشهب، فلا ينجو أن يحترق، أو يصيبه شر منه. قال: فيسقط فلا يعود أبدا. قال: ويرمى بذاك الذي سمع إلى أوليائه من الإنس. قال:", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 1, "imgs": ["030_001_1.png"], "pages": [409], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 8, "title": "معنى: {في أنفسهم}", "mawsua": {"taliq": 5092, "masala": "معنى: {في أنفسهم}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن تكون الفكرة في ذواتهم وحواسهم وخلقتهم؛ ليستدلوا بذلك على الخالق المخترع", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون قوله: {في أنفسهم} ظرفا للفكرة في خلق السماوات والأرض، ثم أخبر عقب هذا المعنى بأن الحق هو السبب في خلق السماوات والأرض", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5092, "mi": 1, "aya": 8, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 10", "qawl": "", "nass": "أن تكون الفكرة في ذواتهم وحواسهم وخلقتهم؛ ليستدلوا بذلك على الخالق المخترع", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 10, "title": "معنى هذه الآية", "mawsua": {"taliq": 5093, "masala": "معنى هذه الآية", "sigha": "ذكر قولين", "nasib": "ابن كثير", "aqwal": [{"n": 1, "t": "أن الكفار إنما «أوتوا من أنفسهم؛ حيث كذبوا بآيات الله، واستهزءوا بها، وما ذاك إلا بسبب ذنوبهم السالفة في تكذيبهم المتقدم، ولهذا قال: {ثم كان عاقبة الذين أساءوا السوأى أن كذبوا بآيات الله وكانوا بها يستهزئون}، كما قال تعالى: {ونقلب أفئدتهم وأبصارهم كما لم يؤمنوا به أول مرة ونذرهم في طغيانهم يعمهون} [الأنعام: 110]، وقوله: {فلما زاغوا أزاغ الله قلوبهم} [الصف: 5]، وقال: {فإن تولوا فاعلم أنما يريد الله أن يصيبهم ببعض ذنوبهم} [المائدة: 49]", "ashab": "", "athar": []}, {"n": 2, "t": "أن المعنى: «{ثم كان عاقبة الذين أساءوا السوأى} أي: كانت السوأى عاقبتهم؛ لأنهم كذبوا بآيات الله، وكانوا بها يستهزئون", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5093, "mi": 1, "aya": 10, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 16", "qawl": "", "nass": "أوتوا من أنفسهم؛ حيث كذبوا بآيات الله، واستهزءوا بها، وما ذاك إلا بسبب ذنوبهم السالفة في تكذيبهم المتقدم، ولهذا قال: {ثم كان عاقبة الذين أساءوا السوأى أن كذبوا بآيات الله وكانوا بها يستهزئون}، كما قال تعالى: {ونقلب أفئدتهم وأبصارهم كما لم يؤمنوا به أول مرة ونذرهم في طغيانهم يعمهون} [الأنعام: 110]، وقوله: {فلما زاغوا أزاغ الله قلوبهم} [الصف: 5]، وقال: {فإن تولوا فاعلم أنما يريد الله أن يصيبهم ببعض ذنوبهم} [المائدة: 49]", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 15, "title": "في معنى ذلك ﴿فأما الذين ءامنوا﴾", "tabari": {"page": "18/471", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معنى ذلك: فهم في روضة يكرمون", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [60450, 60466]}, {"n": 2, "t": "معناه: ينعمون", "taqdim": 0, "n_athar": 2, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [60451, 60455, 60468, 60469]}, {"n": 3, "t": "يلذذون بالسماع والغناء", "taqdim": 0, "n_athar": 4, "qailun": [["قول الله", ""], ["يحيى بن أبى كثير", "تابعي"]], "athar": [60449, 60456]}]}, "mawaqif": [{"taliq": 5096, "mi": 1, "aya": 15, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "18/ 470 - 471", "qawl": "", "nass": "وكل هذه الألفاظ التي ذكرنا عمن ذكرناها عنه تعود إلى معنى ما قلنا", "qawaid": [], "tabi": ""}, {"taliq": 5096, "mi": 1, "aya": 15, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 14", "qawl": "الثالث", "nass": "وهذا نوع من الحبرة", "qawaid": [], "tabi": ""}, {"taliq": 5096, "mi": 1, "aya": 15, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "11/ 17", "qawl": "", "nass": "والحبرة أعم من هذا كله", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["030_002_1.png"], "pages": [409], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5096, "masala": "معنى: {يحبرون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "يكرمون", "ashab": "", "athar": []}, {"n": 2, "t": "ينعمون", "ashab": "", "athar": []}, {"n": 3, "t": "يتلذذون بالسماع والغناء", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 24, "title": "في وجه سقوط \"أن\" في قوله: ﴿يريكم البرق خوفا وطمعا﴾", "tabari": {"page": "18/480", "sarih": 1, "tarjih": "والصواب من القول في ذلك: أن \"من\" في قوله: ﴿ومن ءاياته﴾، تدل على المحذوف، وذلك أنها تأتى بمعنى التبعيض، [وإذا كانت] كذلك، كان معلوما أنها تقتضى البعض، فلذلك تحذف العرب معها الاسم لدلالتها عليه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "لم يذكر هاهنا \"أن\"؛ لأن هذا يدل على المعنى، وقال الشاعر :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إذا أظهرت \"أن\" فهي في موضع رفع؛ كما قال: ﴿ومن ءاياته خلق السماوات﴾، و ﴿منامكم﴾. فإذا حذفت جعلت ﴿من﴾ مؤدية عن اسم متروك، يكون الفعل صلة له ، كقول الشاعر :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "إنما ينبغى أن تحذف \"أن\" من الموضع الذى يدل على حذفها، فأما في كل موضع فلا، فأما مع: \"أحضر الوغى\" ، فلما كان: زجرتك أن تقوم. و: زجرتك لأن تقوم. يدل على الاستقبال، جاز حذف \"أن\"؛ لأن الموضع معروف، لا يقع في كل الكلام، فأما قوله: ومن آياته أنك قائم. و: أنك تقوم. و: أن تقوم. فهذا الموضع لا يحذف؛ لأنه لا يدل على شيء واحد", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 26, "title": "في تأويل ذلك، فنذكر اختلافهم، ثم تبين الصواب عندنا في ذلك من القول", "tabari": {"page": "18/483", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب القول الذي ذكرناه عن ابن عباس، وهو أن كل من في السماوات والأرض من خلق لله، مطبع في تصرفه فيما أراد تعالى ذكره من حياة وموت، وما أشبه ذلك، [وإن عصاه فيما [يكتسبه بقواه] ، وفيما له السبيل إلى اختياره، وإيثاره على خلافه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "ذلك كلام مخرجه مخرج العموم، والمراد به الخصوص، ومعناه: كل له قانتون في الحياة والبقاء والموت، والفناء والبعث والنشور، لا يمتنع عليه شيء من ذلك، وإن عصاه بعضهم في غير ذلك", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}, {"n": 2, "t": "بل معنى ذلك: كل له قانتون بإقرارهم بأنه ربهم وخالقهم", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [60534]}, {"n": 3, "t": "هو على الخصوص، والمعنى: وله من في السماوات والأرض؛ من ملك وعبد مؤمن لله مطيع دون غيرهم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [60538]}]}, "mawaqif": [{"taliq": 5101, "mi": 1, "aya": 26, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 20", "qawl": "الأول", "nass": "فكأنه قال: كل له قانتون في معظم الأمور وفي غالب الشأن", "qawaid": [], "tabi": ""}, {"taliq": 5101, "mi": 1, "aya": 26, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "18/ 484 - 485", "qawl": "الأول", "nass": "لأن العصاة من خلقه فيما لهم السبيل إلى اكتسابه كثير عددهم، وقد أخبر -تعالى ذكره- عن جميعهم أنهم له قانتون، فغير جائز أن يخبر عمن هو عاص أنه له قانت فيما هو له عاص", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "mushid": {"i": 3, "imgs": ["030_003_1.png", "030_003_2.png"], "pages": [409, 410], "n": 3, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5101, "masala": "معنى: {كل له قانتون} من جهة أن ظاهرها العموم، وأن أكثر الجن والإنس لله عاصون", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن ظاهرها العموم والمراد بها الخصوص، والمعنى: كل له قانتون في الحياة والبقاء والموت، والفناء والبعث والنشور، لا يمتنع عليه شيء من ذلك، وإن عصاه بعضهم من غير ذلك", "ashab": "", "athar": []}, {"n": 2, "t": "أن المعنى: كل له قانتون بإقرارهم أنه ربهم وخالقهم", "ashab": "", "athar": []}, {"n": 3, "t": "هي على الخصوص، والمعنى: وله من في السماوات والأرض، من ملك وعبد مؤمن لله مطيع دون غيرهم", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن عطية", "w"], ["ابن جرير", "r"]]}, "t": {"1": [["ابن عطية", "w"], ["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 27, "title": "في معنى قوله: ﴿وهو أهون عليه﴾", "tabari": {"page": "18/485", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معناه: وهو هين عليه", "taqdim": 0, "n_athar": 2, "qailun": [["الربيع بن حثيم", ""], ["ابن عباس", "صحابي"]], "athar": [60541, 60542, 60543, 60556]}, {"n": 2, "t": "معناه: وإعادة الخلق بعد فنائهم أهون عليه من ابتداء خلقهم", "taqdim": 0, "n_athar": 5, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["عكرمة قرأ هذا الحرف", "تابعي"], ["قتادة", "تابعي"]], "athar": [60541, 60542, 60543, 60546, 60551, 60556, 60557, 60558]}]}, "mawaqif": [{"taliq": 5102, "mi": 1, "aya": 27, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 22", "qawl": "الثاني", "nass": "وإن كان الكل من اليسر عليه في حيز واحد وحال متماثلة", "qawaid": ["السياق"], "tabi": ""}], "mushid": {"i": 4, "imgs": ["030_004_1.png"], "pages": [410], "n": 0, "rajih": [], "daif": [], "match": false}, "mawsua": {"taliq": 5102, "masala": "معنى: {وهو أهون عليه}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "وهو هين عليه", "ashab": "", "athar": []}, {"n": 2, "t": "وهو أيسر عليه", "ashab": "", "athar": []}, {"n": 3, "t": "أن الضمير في {عليه} عائد على {الخلق}، أي: والعود أهون على الخلق، بمعنى: أسرع", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 28, "title": "في تأويل قوله: ﴿تخافونهم كخيفتكم أنفسكم﴾", "tabari": {"page": "18/490", "sarih": 1, "tarjih": "وأولى القولين بالصواب في تأويل ذلك هذا القول الثاني؛ لأنه أشبههما بما دل عليه ظاهر الكلام، وذلك أن الله جل ثناؤه وبخ هؤلاء المشركين في الذين جعلوا له من خلقه آلهة يعبدونها، وأشركوهم في عبادتهم إياه ، وهم مع ذلك يقرون بأنها خلقه وهم عبيده، وعيرهم بفعلهم ذلك، فقال لهم: هل لكم من عبيدكم شركاء فيما خولناكم من نعمنا، فهم سواء وأنتم في ذلك، تخافون أن يقاسموكم ذلك المال الذى هو بينكم وبينهم، كخيفة بعضكم بعضا أن يقاسمه ما بينه وبينه من المال شركة؟! فالخيفة التى ذكرها تعالى ذكره بأن تكون خيفة مما يخاف الشريك من مقاسمة شريكه المال الذي بينهما إياه، أشبه من أن تكون خيفة منه بأن يرثه؛ لأن ذكر الشركة لا يدل على خيفة الوراثة، وقد يدل على خيفة الفراق والمقاسمة.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "معنى ذلك: تخافون هؤلاء الشركاء مما ملكت أيمانكم، أن يرثوكم أموالكم من بعد وفاتكم، كما يرث بعضكم بعضا", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [60560, 60562]}, {"n": 2, "t": "بل معنى ذلك: تخافون هؤلاء الشركاء مما ملكت أيمانكم، أن يقاسموكم أموالكم، كما يقاسم بعضكم بعضا", "taqdim": 0, "n_athar": 1, "qailun": [["أبو مجلر", ""]], "athar": []}]}, "mawaqif": [{"taliq": 5103, "mi": 1, "aya": 28, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "18/ 491", "qawl": "الثاني", "nass": "وذلك أن الله -جل ثناؤه- وبخ هؤلاء المشركين في الذين جعلوا له من خلقه آلهة يعبدونها، وأشركوهم في عبادتهم إياه، وهم مع ذلك يقرون بأنها خلقه وهم عبيده، وعيرهم بفعلهم ذلك، فقال لهم: هل لكم من عبيدكم شركاء فيما خولناكم من نعمنا، فهم سواء وأنتم في ذلك، تخافون أن يقاسموكم ذلك المال الذي هو بينكم وبينهم، كخيفة بعضكم بعضا أن يقاسمه ما بينه وبينه من المال شركة؟! فالخيفة التي ذكرها -تعالى ذكره- بأن تكون خيفة مما يخاف الشريك من مقاسمة شريكه المال الذي بينهما إياه، أشبه من أن تكون خيفة منه بأن يرثه؛ لأن ذكر الشركة لا يدل على خيفة الوراثة، وقد يدل على خيفة الفراق والمقاسمة", "qawaid": ["ظاهر الآية ولفظها", "الدلالة العقلية"], "tabi": ""}], "mushid": {"i": 5, "imgs": ["030_005_1.png", "030_005_2.png"], "pages": [410], "n": 4, "rajih": [4], "daif": [], "match": false}, "mawsua": {"taliq": 5103, "masala": "معنى: {تخافونهم كخيفتكم أنفسكم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "تخافون هؤلاء الشركاء مما ملكت أيمانكم أن يرثوكم أموالكم كما يرث بعضكم بعضا", "ashab": "", "athar": []}, {"n": 2, "t": "تخافون أن يقاسموا أموالكم كما يقاسم بعضكم بعضا", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["ظاهر الآية ولفظها", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 30, "title": "معنى", "mawsua": {"taliq": 5106, "masala": "معنى", "sigha": "ذكر قولين", "nasib": "ابن القيم", "aqwal": [{"n": 1, "t": "لا تبديل لدين الله", "ashab": "", "athar": []}, {"n": 2, "t": "هو الخصاء. ثم جمع بينهما بقوله: «ولا منافاة بين القولين، كما قال تعالى: {ولآمرنهم فليبتكن آذان الأنعام ولآمرنهم فليغيرن خلق الله} [النساء: 119]، فتغيير ما فطر الله عباده من الدين تغيير لخلقه، والخصا وقطع آذان الأنعام تغيير لخلقه أيضا، ولهذا شبه النبي صلى الله عليه وسلم أحدهما بالآخر؛ فأولئك يغيرون الشريعة، وهؤلاء يغيرون الخلقة، فذلك يغير ما خلقت عليه نفسه وروحه، وهذا يغير ما خلق عليه بدنه", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5106, "mi": 1, "aya": 30, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 312", "qawl": "", "nass": "ولا منافاة بين القولين، كما قال تعالى: {ولآمرنهم فليبتكن آذان الأنعام ولآمرنهم فليغيرن خلق الله} [النساء: 119]، فتغيير ما فطر الله عباده من الدين تغيير لخلقه، والخصا وقطع آذان الأنعام تغيير لخلقه أيضا، ولهذا شبه النبي صلى الله عليه وسلم أحدهما بالآخر؛ فأولئك يغيرون الشريعة، وهؤلاء يغيرون الخلقة، فذلك يغير ما خلقت عليه نفسه وروحه، وهذا يغير ما خلق عليه بدنه", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 39, "title": "تأويل: ﴿وما آتيتم من ربا ليربو في أموال الناس فلا يربو عند الله وما آتيتم من زكاة تريدون وجه الله ﴾", "tabari": {"page": "18/505", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: وما أعطيتم أيها الناس بعضكم بعضا من عطية؛ لتزداد في أموال الناس، برجوع ثوابها إليه، ممن أعطاه ذلك، ﴿فلا يربوا عند الله﴾. يقول: فلا يزداد ذلك عند الله؛ لأن صاحبه لم يعطه من أعطاه مبتغيا به وجهه. ﴿وما آتيتم من ذكاة﴾. يقول: وما أعطيتم من صدقة تريدون بها وجه الله. ﴿فأولئك﴾، يعنى الذين يتصدقون بأموالهم ملتمسين بذلك وجه الله، ﴿هم المضعفون﴾. يقول: هم الذين لهم الضعف من الأجر والثواب. من ", "taqdim": 1, "n_athar": 9, "qailun": [["ابن عباس", "صحابي"], ["سعيد بن جبير", "تابعي"], ["مجاهد", "تابعي"], ["إبراهيم", "تابعي"], ["قتادة", "تابعي"]], "athar": [60651, 60653, 60654, 60655, 60656, 60657, 60658, 60659, 60660, 60661, 60662, 60663, 60664, 60666, 60674, 60678, 60679, 60680]}, {"n": 2, "t": "إنما عنى بهذا الرجل يعطى ماله الرجل ليعينه بنفسه، ويخدمه ويعود عليه نفعه، لا لطلب أجر من الله", "taqdim": 0, "n_athar": 1, "qailun": [["عامر", "تابعي"]], "athar": [60670]}, {"n": 3, "t": "هو إعطاء الرجل ماله؛ ليكثر به مال من أعطاه ذلك، لا لطلب ثواب الله", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [60651, 60653, 60654, 60655, 60656, 60666, 60678]}, {"n": 4, "t": "ذلك للنبي ﷺ خاصة، وأما لغيره فحلال", "taqdim": 0, "n_athar": 1, "qailun": [["الضحاك", "تابعي"]], "athar": [60665, 60667, 60668]}]}, "mawaqif": [{"taliq": 5112, "mi": 1, "aya": 39, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "18/ 506", "qawl": "الأول", "nass": "وإنما اخترنا القول الذي اخترناه في ذلك لأنه أظهر معانيه", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 5112, "mi": 1, "aya": 39, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 28", "qawl": "الأول", "nass": "قال ابن عباس، وابن جبير، ومجاهد، وطاووس: هذه آية نزلت في هبات الثواب، وما جرى مجراها مما يصنعه الإنسان ليجازى عليه؛ كالسلام وغيره، فهو وإن كان لا إثم فيه فلا أجر فيه ولا زيادة عند الله تعالى", "qawaid": [], "tabi": ""}], "mushid": {"i": 7, "imgs": ["030_007_1.png"], "pages": [411], "n": 5, "rajih": [1], "daif": [], "match": false}, "mawsua": {"taliq": 5112, "masala": "معنى الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه الرجل يهدي هدية ليكافأ عليها أفضل منها", "ashab": "", "athar": []}, {"n": 2, "t": "أنه في رجل صحبه في الطريق فخدمه، فجعل له المخدوم بعض الربح من ماله جزاء لخدمته، لا لوجه الله", "ashab": "", "athar": []}, {"n": 3, "t": "أنه في رجل يهب لذي قرابة له مالا ليصير به غنيا ذا مال، ولا يفعله طلبا لثواب الله", "ashab": "", "athar": []}, {"n": 4, "t": "أن ذلك للنبي صلى الله عليه وسلم خاصة، وأما لغيره فحلال", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["ظاهر الآية ولفظها"]}, "rulesD": {}}}, {"aya": 41, "title": "تأويل: ﴿ظهر الفساد في البر والبحر﴾", "tabari": {"page": "18/511", "sarih": 0, "tarjih": "وأولى الأقوال في ذلك بالصواب أن الله تعالى ذكره أخبر أن الفساد قد ظهر في البر والبحر. والبر عند العرب : الأرض القفار، والبحر بحران؛ بحر ملح، وبحر عذب، وهما جميعا عندهم بحر، ولم يخصص جل ثناؤه الخبر عن ظهور ذلك في بحر دون بحر، فذلك على ما وقع عليه اسم بحر؛ عذبا كان أو ملحا. وإذا كان كذلك، دخل القرى التي على الأنهار والبحار.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "﴿ظهر الفساد في البر والبحر﴾؛ أما البر فأهل العمود ، وأما البحر فأهل القرى والريف.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "بل عنى بالبر ظهر الأرض؛ الأمصار وغيرها، وبالبحر البحر المعروف", "taqdim": 0, "n_athar": 4, "qailun": [["مجاهد", "تابعي"], ["عطية", "تابعي"]], "athar": [60692, 60693, 60701, 60702]}]}, "mawaqif": [{"taliq": 5114, "mi": 1, "aya": 41, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "18/ 512", "qawl": "", "nass": "أن الله -تعالى ذكره- أخبر أن الفساد قد ظهر في البر والبحر، والبر عند العرب: الأرض القفار. والبحر بحران: بحر ملح، وبحر عذب، وهما جميعا عندهم بحر. ولم يخصص -جل ثناؤه- الخبر عن ظهور ذلك في بحر دون بحر، فذلك على ما وقع عليه اسم بحر عذبا كان أو ملحا، وإذا كان ذلك كذلك دخل القرى التي على الأنهار والبحار", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 5114, "mi": 1, "aya": 41, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 30 - 31", "qawl": "الثالث", "nass": "وقال الحسن: البر والبحر هما المعروفان المشهوران في اللغة. وهذا القول صحيح", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 5114, "mi": 1, "aya": 41, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "11/ 34", "qawl": "الأول", "nass": "والقول الأول أظهر، وعليه الأكثر، ويؤيده ما ذكره محمد بن إسحاق في السيرة: أن رسول الله صلى الله عليه وسلم صالح ملك أيلة، وكتب إليه ببحره، يعني: ببلده", "qawaid": ["السنة"], "tabi": ""}], "mushid": {"i": 8, "imgs": ["030_008_1.png"], "pages": [411], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5114, "masala": "تفسير قوله: {ظهر الفساد في البر والبحر}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن البر: هو الفيافي. والبحر: القرى والأمصار", "ashab": "", "athar": []}, {"n": 2, "t": "البر: أهل العمود. والبحر: أهل القرى والريف", "ashab": "", "athar": []}, {"n": 3, "t": "البر: ظهر الأرض؛ الأمصار وغيرها. والبحر: هو البحر المعروف", "ashab": "", "athar": []}]}, "tags": {"m": {"3": [["ابن عطية", "r"]], "1": [["ابن كثير", "r"]]}, "t": {"2": [["ابن عطية", "r"]]}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["اللغة"], "ابن عطية": ["اللغة"], "ابن كثير": ["السنة"]}, "rulesD": {}}}, {"aya": 48, "title": "عود الضمير من قوله: {من خلاله}", "mawsua": {"taliq": 5117, "masala": "عود الضمير من قوله: {من خلاله}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يعود على السحاب. كما ورد في أقوال السلف", "ashab": "", "athar": []}, {"n": 2, "t": "أن يعود على الكسف، وذلك على قراءة من سكن السين فيها", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5117, "mi": 1, "aya": 48, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 33", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 50, "title": "فاعل {يحي}", "mawsua": {"taliq": 5119, "masala": "فاعل {يحي}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون الضمير الذي في الفعل للأثر", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون لله تعالى", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5119, "mi": 1, "aya": 50, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 34", "qawl": "", "nass": "وقوله {كيف يحي} يحتمل أن يكون الضمير الذي في الفعل للأثر، ويحتمل أن يكون لله تعالى", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}], "extra": [{"i": 6, "aya": 28, "imgs": ["030_006_1.png"], "pages": [410], "ihala": 0}, {"i": 9, "aya": 41, "imgs": ["030_009_1.png"], "pages": [411], "ihala": 0}], "others": {"0": [{"id": 5082, "kinds": "تعليق،نقل", "text": "نقل ابنُ عطية (7/ 7) عن الناس: «أن سبب سرور المسلمين بغَلَبَة الروم وهمِّهم أن تَغْلِب، وكون المشركين من قريش على ضد ذلك؛ إنما هو أن الروم أهل كتاب كالمسلمين، والفرس أهل الأوثان ونحوه من عبادة النار ككفار قريش والعرب». ثم علَّق على هذا الكلام بقوله: «ويشبه أن يقال ذلك بما يقتضيه النظر من محبة أن يغلب العدوّ الأصغر؛ لأنه أيسر مؤونة، ومتى غلب الأكبر كثر الخوف منه، فتأمل هذا المعنى مع ما كان رسول الله صلى الله عليه وسلم ترجّاه من ظهور دينه وشَرْعِ الله تعالى عز وجل الذي بعثه به، وغلبته على الأمم، وإرادة كفار مكة أن يرميه الله بمَلِك يستأصله ويريحهم منه».", "mawaqif": [{"taliq": 5082, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 7", "qawl": "", "nass": "أن سبب سرور المسلمين بغلبة الروم وهمهم أن تغلب، وكون المشركين من قريش على ضد ذلك؛ إنما هو أن الروم أهل كتاب كالمسلمين، والفرس أهل الأوثان ونحوه من عبادة النار ككفار قريش والعرب", "qawaid": [], "tabi": ""}]}, {"id": 5083, "kinds": "تعليق", "text": "علّق ابنُ كثير (11/ 10) على هذا الأثر قائلًا: «هذا سياق غريب، وبناء عجيب».", "mawaqif": [{"taliq": 5083, "mi": 0, "aya": 0, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "11/ 10", "qawl": "", "nass": "هذا سياق غريب، وبناء عجيب", "qawaid": [], "tabi": ""}]}], "3": [{"id": 5084, "kinds": "بيان،تعليق", "text": "علَّق ابنُ عطية (7/ 5) على قول مجاهد بقوله: «وهو موضع بين العراق والشام».", "mawaqif": [{"taliq": 5084, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 5", "qawl": "مجاهد بقوله", "nass": "وهو موضع بين العراق والشام", "qawaid": [], "tabi": ""}]}, {"id": 5085, "kinds": "بيان،تعليق", "text": "علَّق ابنُ عطية (7/ 5) على قول عكرمة بقوله: «وهي بين بلاد العرب والشام».", "mawaqif": [{"taliq": 5085, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 5", "qawl": "عكرمة بقوله", "nass": "وهي بين بلاد العرب والشام", "qawaid": [], "tabi": ""}]}, {"id": 5086, "kinds": "توجيه", "text": "وجَّه ابنُ عطية (7/ 6) قول مجاهد، وعكرمة، ومقاتل، وما في معناها بقوله: «فإن كانت الوقعة في أذرعات فهي من أدنى الأرض بالقياس إلى مكة … وإن كانت الوقعة بالجزيرة فهي أدنى بالقياس إلى أرض كسرى، وإن كانت بالأردن فهي أدنى إلى أرض الروم».", "mawaqif": [{"taliq": 5086, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 6", "qawl": "مجاهد", "nass": "فإن كانت الوقعة في أذرعات فهي من أدنى الأرض بالقياس إلى مكة … وإن كانت الوقعة بالجزيرة فهي أدنى بالقياس إلى أرض كسرى، وإن كانت بالأردن فهي أدنى إلى أرض الروم", "qawaid": [], "tabi": ""}]}], "4": [{"id": 5087, "kinds": "نقد،نقل", "text": "نقل ابنُ عطية (7/ 7) عن أبي عبيدة أن «البضع: من الثلاث إلى الخمس». ثم انتقده قائلًا: «وقوله مردود».", "mawaqif": [{"taliq": 5087, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 7", "qawl": "", "nass": "البضع: من الثلاث إلى الخمس", "qawaid": [], "tabi": ""}]}], "6": [{"id": 5090, "kinds": "ترجيح،نقد،نقل", "text": "ذكر ابنُ عطية (7/ 9) في معنى قوله تعالى: {وعْدَ اللَّهِ لا يُخْلِفُ اللَّهُ وعْدَهُ ولَكِنَّ أكْثَرَ النّاسِ لا يَعْلَمُونَ}: أنّ الكُفّار من قريش والعرب لا يعلمون أنّ الأمور مِن عند الله تبارك وتعالى، وأن وعْده لا يتخلَّف، وأن ما يورده نبيه عليه الصلاة والسلام حقٌّ. ورجَّح هذا المعنى قائلًا: «وهذا الذي ذكرناه هو عمدة ما قيل». ثم انتقد مستندًا إلى الإجماع ما حكاه ابنُ جرير من روايات للنزول تفيد مدنية الآية، فقال: «وقد حكى الطبريُّ وغيرُه روايات يردُّها النظر أوَّل قول، من ذلك أن بعضهم قال: إنما نزلت {وعْدَ اللَّهِ لا يُخْلِفُ اللَّهُ وعْدَهُ} بعد غلبة الروم لفارس ووصول الخبر بذلك. فهذا يقتضي أن الآية مدنية، والسورة كلها مكية بإجماع، ونحو هذا من الأقوال».", "mawaqif": [{"taliq": 5090, "mi": 0, "aya": 6, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 9", "qawl": "", "nass": "وهذا الذي ذكرناه هو عمدة ما قيل", "qawaid": ["الإجماع"], "tabi": ""}]}], "7": [{"id": 5091, "kinds": "توجيه،تعليق،نقل", "text": "نقل ابنُ عطية (7/ 9) في معنى: {ظاهِرًا} في هذه الآية أقوالًا أخرى: الأول: «معناه: بيِّنًا». ووجَّهه بقوله: «أي: ما أدَّته إليهم حواسهم، فكأن علومهم إنما هي علوم البهائم». الثاني: «معناه: ذاهبًا زائلًا». ووجَّهه بقوله \"أي: يعلمون من أمور الدنيا التي لا بقاء لها ولا عاقبة، ومثل هذه اللفظة قول الهُذَلي:\nوعَيَّرَها الواشون أني أُحِبُّها … وتِلْكَ شَكاةٌ ظاهرٌ عنك عارُها\".الثالث: «قال الرماني: كل ما يُعلم بأوائل الرؤية فهو الظاهر، وما يعلم بدليل العقل فهو الباطن». وعلَّق (7/ 10) عليه بقوله: «وفيه تقع الغفلة، وتقصير الجهال».", "mawaqif": [{"taliq": 5091, "mi": 0, "aya": 7, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 9", "qawl": "", "nass": "معناه: بينا", "qawaid": [], "tabi": ""}]}], "12": [{"id": 5094, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (18/ 468 - 469) في معنى: {يُبْلِسُ المُجْرِمُونَ} سوى قول مجاهد من طريق ابن أبي نجيح، وقتادة من طريق سعيد، وابن زيد.", "mawaqif": []}], "14": [{"id": 5095, "kinds": "توجيه", "text": "وجَّه ابنُ كثير (11/ 17) قول قتادة بقوله: «يعني: إذا رفع هذا إلى عليين، وخفض هذا إلى أسفل السافلين؛ فذاك آخر العهد بينهما».", "mawaqif": [{"taliq": 5095, "mi": 0, "aya": 14, "alam": "ابن كثير", "fil": "وجه", "kind": "توجيه", "ref": "11/ 17", "qawl": "قتادة بقوله", "nass": "يعني: إذا رفع هذا إلى عليين، وخفض هذا إلى أسفل السافلين؛ فذاك آخر العهد بينهما", "qawaid": [], "tabi": ""}]}], "19": [{"id": 5097, "kinds": "تعليق،نقل", "text": "علَّق ابنُ عطية (7/ 16) على قول الحسن بقوله: «وروي هذا المعنى عن النبي صلى الله عليه وسلم أنه قرأ هذه الآية عند ما كلَّمَتْه بالإسلام أم كلثوم بنت عقبة بن أبي معيط».", "mawaqif": [{"taliq": 5097, "mi": 0, "aya": 19, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 16", "qawl": "الحسن بقوله", "nass": "وروي هذا المعنى عن النبي صلى الله عليه وسلم أنه قرأ هذه الآية عند ما كلمته بالإسلام أم كلثوم بنت عقبة بن أبي معيط", "qawaid": [], "tabi": ""}]}], "21": [{"id": 5098, "kinds": "توجيه،تعليق", "text": "علَّق ابن عطية (7/ 17) على قول قتادة بقوله: «فحمل ذلك على جميع الناس من حيث أُمُّهم مخلوقة من نفس آدم، أي: من ذات شخصه».", "mawaqif": [{"taliq": 5098, "mi": 0, "aya": 21, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 17", "qawl": "قتادة بقوله", "nass": "فحمل ذلك على جميع الناس من حيث أمهم مخلوقة من نفس آدم، أي: من ذات شخصه", "qawaid": [], "tabi": ""}]}], "22": [{"id": 5099, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 17) في معنى: {وأَلْوانِكُمْ} احتمالًا، فقال: «ويحتمل أن يريد: ضروب بني آدم وأنواعهم». وعلَّق عليه بقوله: «فتَعُمُّ شخوص البشر الذين يختلفون بالألوان، وتَعُمُّ الألسنة».", "mawaqif": [{"taliq": 5099, "mi": 0, "aya": 22, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 17", "qawl": "", "nass": "ويحتمل أن يريد: ضروب بني آدم وأنواعهم", "qawaid": [], "tabi": ""}]}], "24": [{"id": 5100, "kinds": "نقد،توجيه", "text": "لم يذكر ابنُ جرير (18/ 480) في معنى: {يُرِيكُمُ البَرْقَ خَوْفًا وطَمَعًا} سوى قول قتادة.\nوانتقد ابنُ عطية (7/ 19) قول قتادة مستندًا إلى العموم قائلًا: «ولا وجْه لهذا التخصيص ونحوه، بل الخوف والطمع لكل البشر».", "mawaqif": [{"taliq": 5100, "mi": 0, "aya": 24, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 19", "qawl": "قتادة مستندا", "nass": "ولا وجه لهذا التخصيص ونحوه، بل الخوف والطمع لكل البشر", "qawaid": ["العموم"], "tabi": ""}]}], "30": [{"id": 5104, "kinds": "خلاف،توجيه،تعليق،نقل", "text": "ذهب ابنُ عطية (7/ 23، 24) في معنى «الفطرة» إلى أن «الذي يعتمد عليه في تفسير هذه اللفظة أنها: الخِلْقة والهيئة التي في نفس الطفل التي هي مُعدَّة مُهَيَّأة لأن يُمَيِّز بها مصنوعات الله تعالى، ويَسْتَدل بها على ربه جَلَّ وعلا، ويعرف شرائعه، ويؤمن به». ووجَّه معنى الآية عليه بقوله: «فكأنه تعالى قال: أقم وجْهك لِلدِّينِ الذي هو الحنيف، وهو فِطْرَة اللهِ الذي على الإعداد له فطر البشر». ثم علَّق بقوله: «لكن تعرضهم العوارض، ومنه قول النبي صلى الله عليه وسلم: «كل مولود يولد على الفطرة، فأبواه يُهَوِّدانه أو يُنَصِّرانه … » الحديث، وذِكْرُ الأبوين إنما هو مثال للعوارض التي هي كثيرة».\nوذكر ابنُ عطية اختلافًا في «الفطرة»، فقال: «واختلف الناس في» الفطرة «ها هنا، فذكر مكيٌّ وغيرُه في ذلك جميعَ ما يمكن أن تصرف هذه اللفظة عليه». وعلَّق بقوله: «وفي بعض ذلك قلق».", "mawaqif": [{"taliq": 5104, "mi": 0, "aya": 30, "alam": "ابن عطية", "fil": "ذهب", "kind": "قول", "ref": "7/ 23، 24", "qawl": "", "nass": "الفطرة", "qawaid": [], "tabi": ""}, {"taliq": 5104, "mi": 0, "aya": 30, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "الفطرة", "qawaid": [], "tabi": ""}]}, {"id": 5105, "kinds": "ترجيح،توجيه،نقل", "text": "وجَّه ابنُ عطية (7/ 24) قول سعيد بن جبير وما في معناه بقوله: «وهذا معناه: لا تبديل للمعتقدات التي هي في الدين الحنيف، فإن كل شريعة هي عقائدها». يعني: أن كل شريعة من شرائع الأنبياء عقائدها هي عقائد الأخرى لا تختلف.\nثم ذكر في معنى الآية احتمالين: الأول: «أن يريد بها: هذه الفطرة المذكورة». ووجَّهه بقوله: «أي: اعلم أن هذه الفطرة لا تبديل لها من جهة الخالق، ولا يجيء الأمر على خلافها بوجه». والثاني: «أن يكون قوله: {لا تَبْدِيلَ لِخَلْقِ اللَّهِ} إنحاءً على الكفرة، واعترض به أثناء الكلام». ووجَّهه بقوله: «كأنه يقول: أقِم وجهك للدين الذي مِن صفته كذا وكذا، فإن هؤلاء الكفار الذين خلق الله لهم الكفر، ولا تبديل لخلق الله، أي: أنهم لا يفلحون».\nورجَّح ابنُ تيمية (5/ 161) مستندًا إلى ظاهر اللفظ أنّ قوله تعالى: {لا تبديل لخلق الله} خبرٌ على ظاهره بأنّ خلق الله لا يُبَدِّله أحد، وأنّ هذا أصحُّ مِمَّن جعل معناه النهي، فلا يجعل نهيًا بغير حجة.", "mawaqif": [{"taliq": 5105, "mi": 0, "aya": 30, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 24", "qawl": "سعيد بن", "nass": "وهذا معناه: لا تبديل للمعتقدات التي هي في الدين الحنيف، فإن كل شريعة هي عقائدها", "qawaid": [], "tabi": ""}, {"taliq": 5105, "mi": 0, "aya": 30, "alam": "ابن تيمية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 161", "qawl": "", "nass": "", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}]}], "32": [{"id": 5107, "kinds": "توجيه،تعليق،نقل،حصر", "text": "لم يذكر ابنُ جرير (18/ 498) غير قول ابن زيد، وقول قتادة، ثم قال: «فلو وجه قوله: {من الذين فرقوا دينهم} إلى أنه خبر مستأنف منقطع عن قوله: {ولا تكونوا من المشركين}، وأن معناه: {من الذين فرقوا دينهم وكانوا شيعا} أحزابًا، {كل حزب بما لديهم فرحون} كان وجهًا يحتمله الكلام».\nوذكر ابنُ عطية (7/ 25) قول ابن زيد، وقولًا آخر نسبه إلى أبي هريرة، وعائشة أم المؤمنين: أنّ الآية في أهل القبلة. ثم علّق عليه بقوله: «فلفظة الإشراك على هذا فيها تَجَوُّز؛ فإنهم صاروا في دينهم فِرَقًا».", "mawaqif": [{"taliq": 5107, "mi": 0, "aya": 32, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 25", "qawl": "ابن زيد", "nass": "فلفظة الإشراك على هذا فيها تجوز؛ فإنهم صاروا في دينهم فرقا", "qawaid": [], "tabi": ""}]}], "34": [{"id": 5108, "kinds": "خلاف،ترجيح،نقل", "text": "ذكر ابنُ كثير (11/ 31) في اللام من قوله: {ليكفروا} قولين، فقال: «وقوله: {ليكفروا بما آتيناهم} هي لام العاقبة عند بعضهم، ولام التعليل عند آخرين». ثم رجّح مستندًا إلى الدلالة العقلية أنها للتعليل بقوله: «ولكنها تعليل؛ لتقييض الله لهم ذلك».", "mawaqif": [{"taliq": 5108, "mi": 0, "aya": 34, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 31", "qawl": "", "nass": "وقوله: {ليكفروا بما آتيناهم} هي لام العاقبة عند بعضهم، ولام التعليل عند آخرين", "qawaid": ["الدلالة العقلية"], "tabi": ""}]}], "35": [{"id": 5109, "kinds": "تعليق،نقل،حصر", "text": "لم يذكر ابنُ جرير (18/ 500) غير قول قتادة.\nوذكره ابنُ عطية (7/ 27)، وعلّق عليه فقال: «{فَهُوَ يَتَكَلَّمُ} معناه: أنه يُظهر حجتهم، ويُغَلب مذهبهم، وينطق بشركهم. قاله قتادة، فيقوم بذلك مقام الكلام، كما قال تعالى: {هذا كِتابُنا يَنْطِقُ عَلَيْكُمْ بِالحَقِّ} [الجاثية: 29]».", "mawaqif": [{"taliq": 5109, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "7/ 27", "qawl": "", "nass": "{فهو يتكلم} معناه: أنه يظهر حجتهم، ويغلب مذهبهم، وينطق بشركهم. قاله قتادة، فيقوم بذلك مقام الكلام، كما قال تعالى: {هذا كتابنا ينطق عليكم بالحق} [الجاثية: 29]", "qawaid": [], "tabi": ""}]}], "38": [{"id": 5110, "kinds": "بيان،نقل", "text": "ذكر ابنُ عطية (7/ 28) قول الحسن، ثم أردف معلّقًا: «ومعظم ما قصد أمر المعونة بالمال، ومنه قول النبي صلى الله عليه وسلم: «في المال حق سوى الزكاة». وكذلك للمسكين وابن السبيل حق، وبين أن حق هذين إنما هو في المال وغير ذلك، وكذلك يلزم القريب المعدم الذي يُقضى حقه أن يقضي هو أيضًا حق قريبه في جودة العشرة».", "mawaqif": [{"taliq": 5110, "mi": 0, "aya": 38, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 28", "qawl": "الحسن", "nass": "ومعظم ما قصد أمر المعونة بالمال، ومنه قول النبي صلى الله عليه وسلم: «في المال حق سوى الزكاة", "qawaid": [], "tabi": ""}]}], "39": [{"id": 5111, "kinds": "خلاف،ترجيح،تعليق،نقل", "text": "ذكر ابنُ جرير (18/ 507) هذه القراءة وقراءة من قرأ ذلك {ليربو}، ووجههما، فقال: «واختلفت القراء في قراءة ذلك؛ فقرأته عامة قراء الكوفة والبصرة وبعض أهل مكة: {ليربو} بفتح الياء من يربو، بمعنى: وما آتيتم من ربًا ليربو ذلك الربا في أموال الناس. وقرأ ذلك عامة قراء أهل المدينة: «لِتُرْبُواْ»، بالتاء من تربو، وضمها، بمعنى: وما آتيتم من ربًا لتربوا أنتم في أموال الناس». ثم اختار صوابهما قائلًا: «والصواب من القول في ذلك عندنا أنهما قراءتان مشهورتان في قراء الأمصار مع تقارب معنييهما؛ لأن أرباب المال إذا أربوا ربا المال، وإذا ربا المال فبإرباء أربابه إيّاه رَبا. فإذا كان ذلك كذلك فبأي القراءتين قرأ القارئ فمصيب».\nوعلّق ابنُ عطية (7/ 29) على قراءة التاء، فقال: «وقرأ نافع وحده «لِتُرْبُواْ» بضم التاء، بمعنى: ذوي زيادات».", "mawaqif": [{"taliq": 5111, "mi": 0, "aya": 39, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "18/ 507", "qawl": "", "nass": "واختلفت القراء في قراءة ذلك؛ فقرأته عامة قراء الكوفة والبصرة وبعض أهل مكة: {ليربو} بفتح الياء من يربو، بمعنى: وما آتيتم من ربا ليربو ذلك الربا في أموال الناس. وقرأ ذلك عامة قراء أهل المدينة: «لتربوا", "qawaid": [], "tabi": ""}, {"taliq": 5111, "mi": 0, "aya": 39, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 29", "qawl": "", "nass": "وقرأ نافع وحده «لتربوا", "qawaid": [], "tabi": ""}]}], "41": [{"id": 5113, "kinds": "تعليق،نقل", "text": "ذكر ابن عطية (7/ 30) قول قتادة، وعلّق عليه قائلًا: «ومنه قول سعد بن عبادة للنبي صلى الله عليه وسلم في شأن عبد الله بن أبي ابن سلول:» ولقد أجمع أهل هذه البحيرة على أن يتوجوه «الحديث. ومما يؤيد هذا أن عكرمة قرأ: (فِي البَرِّ والبُحُورِ)».", "mawaqif": [{"taliq": 5113, "mi": 0, "aya": 41, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 30", "qawl": "قتادة", "nass": "ومنه قول سعد بن عبادة للنبي صلى الله عليه وسلم في شأن عبد الله بن أبي ابن سلول:", "qawaid": [], "tabi": ""}]}, {"id": 5115, "kinds": "توجيه،نقل", "text": "وجّه ابنُ جرير (18/ 514) هذه القراءة، فقال: «وذكر أن أبا عبد الرحمن السلمي قرأ ذلك بالنون على وجه الخبر من الله عن نفسه بذلك».", "mawaqif": [{"taliq": 5115, "mi": 0, "aya": 41, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "18/ 514", "qawl": "", "nass": "وذكر أن أبا عبد الرحمن السلمي قرأ ذلك بالنون على وجه الخبر من الله عن نفسه بذلك", "qawaid": [], "tabi": ""}]}, {"id": 5116, "kinds": "ترجيح،بيان،تعليق،نقل", "text": "ذكر ابنُ القيم (2/ 314 - 315) قول ابن زيد، ثم علّق عليه بقوله: «قلت: أراد أنّ الذنوب سبب الفساد الذي ظهر. وإن أراد: أن الفساد الذي ظهر هو الذنوب نفسها؛ فتكون اللام في قوله: {ليذيقهم بعض الذي عملوا} لام العاقبة والتعليل».\nورجّح ابنُ القيم مستندًا إلى السياق أن المراد بالفساد: هو الذنوب وموجباتها، فقال: «والظاهر -والله أعلم- أنّ الفساد المراد به: الذنوب وموجباتها، ويدل عليه قوله تعالى: {ليذيقهم بعض الذي عملوا} فهذا حالنا، وإنما أذاقنا الشيء اليسير من أعمالنا، ولو أذاقنا كلَّ أعمالنا لما ترك على ظهرها من دابة».\nوذكر ابنُ كثير (11/ 35) عن ابن زيد أنه فسر الفساد بالشرك، ثم علّق بقوله: «وفيه نظر».", "mawaqif": [{"taliq": 5116, "mi": 0, "aya": 41, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 314 - 315", "qawl": "ابن زيد", "nass": "قلت: أراد أن الذنوب سبب الفساد الذي ظهر. وإن أراد: أن الفساد الذي ظهر هو الذنوب نفسها؛ فتكون اللام في قوله: {ليذيقهم بعض الذي عملوا} لام العاقبة والتعليل", "qawaid": [], "tabi": ""}, {"taliq": 5116, "mi": 0, "aya": 41, "alam": "ابن القيم", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "والظاهر -والله أعلم- أن الفساد المراد به: الذنوب وموجباتها، ويدل عليه قوله تعالى: {ليذيقهم بعض الذي عملوا} فهذا حالنا، وإنما أذاقنا الشيء اليسير من أعمالنا، ولو أذاقنا كل أعمالنا لما ترك على ظهرها من دابة", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 5116, "mi": 0, "aya": 41, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 35", "qawl": "", "nass": "وفيه نظر", "qawaid": [], "tabi": ""}]}], "49": [{"id": 5118, "kinds": "نقل", "text": "أورد ابنُ تيمية (5/ 188 - 189) استشكال بعض الناس لتكرير قوله تعالى: {قبله} بعدما قال: {وإن كانوا من قبل}، ثم أجاب? بقوله: «وأما قوله: {من قبل أن ينزل عليهم من قبله} فليس من التكرار، بل تحته معنى دقيق، والمعنى فيه: وإن كانوا من قبل أن ينزل عليهم الودق من قبل هذا النزول لمبلسين؛ فهنا قبليتان: قبلية لنزوله مطلقًا، وقبلية لذلك النزول المعين أن لا يكون متقدمًا على ذلك الوقت، فيئسوا قبل نزوله يأسين: يأسًا لعدمه مرئيًا، ويأسًا لتأخره عن وقته؛ فقبل الأولى ظرف اليأس، وقبل الثانية ظرف المجيء والإنزال. ففي الآية ظرفان معمولان وفعلان مختلفان عاملان فيهما، وهما الإنزال والإبلاس؛ فأحد الظرفين متعلق بالإبلاس، والثاني متعلق بالنزول، وتمثيل هذا: أن تقول إذا كنت معتادًا للعطاء من شخص فتأخر عن ذلك الوقت ثم أتاك به: قد كنتُ آيِسًا».", "mawaqif": [{"taliq": 5118, "mi": 0, "aya": 49, "alam": "ابن تيمية", "fil": "أورد", "kind": "نقل", "ref": "5/ 188 - 189", "qawl": "", "nass": "وأما قوله: {من قبل أن ينزل عليهم من قبله} فليس من التكرار، بل تحته معنى دقيق، والمعنى فيه: وإن كانوا من قبل أن ينزل عليهم الودق من قبل هذا النزول لمبلسين؛ فهنا قبليتان: قبلية لنزوله مطلقا، وقبلية لذلك النزول المعين أن لا يكون متقدما على ذلك الوقت، فيئسوا قبل نزوله يأسين: يأسا لعدمه مرئيا، ويأسا لتأخره عن وقته؛ فقبل الأولى ظرف اليأس، وقبل الثانية ظرف المجيء والإنزال. ففي الآية ظرفان معمولان وفعلان مختلفان عاملان فيهما، وهما الإنزال والإبلاس؛ فأحد الظرفين متعلق بالإبلاس، والثاني متعلق بالنزول، وتمثيل هذا: أن تقول إذا كنت معتادا للعطاء من شخص فتأخر عن ذلك الوقت ثم أتاك به: قد كنت آيسا", "qawaid": [], "tabi": ""}]}], "51": [{"id": 5120, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 35): «والضمير في {فرأوه} للنبات كما قلنا، أو للأثر وهو حُوَّة النبات الذي أحييت به الأرض. وقال قوم: هو للسحاب. وقال قوم: هو للريح، وهذا كله ضعيف».", "mawaqif": [{"taliq": 5120, "mi": 0, "aya": 51, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 35", "qawl": "", "nass": "والضمير في {فرأوه} للنبات كما قلنا، أو للأثر وهو حوة النبات الذي أحييت به الأرض. وقال قوم: هو للسحاب. وقال قوم: هو للريح، وهذا كله ضعيف", "qawaid": [], "tabi": ""}]}], "52": [{"id": 5121, "kinds": "نقد،تعليق،نقل", "text": "ذكر ابنُ تيمية (5/ 189) هذا الأثر، ثم علّق على استدراك عائشة على ابن عمر، فقال: «وعائشة تأولت فيما ذكرته كما تأولت أمثال ذلك. والنص الصحيح عن النبي صلى الله عليه وسلم، مُقَدَّم على تأويل مَن تأول مِن أصحابه وغيره، وليس في القرآن ما ينفي ذلك؛ فإن قوله: {إنك لا تسمع الموتى} إنما أراد به السماع المعتاد الذي ينفع صاحبه، فإن هذا مثل ضرب للكفار، والكفار تسمع الصوت، لكن لا تسمع سماع قبولٍ بفقه واتباع، كما قال تعالى: {ومثل الذين كفروا كمثل الذي ينعق بما لا يسمع إلا دعاء ونداء} [البقرة: 171]».\nوقال ابنُ كثير (11/ 39 - 40): «وقد استدلت أم المؤمنين عائشة رضي الله عنها- بهذه الآية: {إنك لا تسمع الموتى} على توهيم عبد الله بن عمر في روايته مخاطبة النبي صلى الله عليه وسلم القتلى الذين ألقوا في القليب قليب بدر بعد ثلاثة أيام، ومعاتبته إياهم، وتقريعه لهم، حتى قال له عمر: يا رسول الله، ما تخاطب مِن قوم قد جيفوا؟ فقال: «والذي نفسي بيده، ما أنتم بأسمع لما أقول منهم، ولكن لا يجيبون». وتأولته عائشة على أنه قال: إنهم الآن ليعلمون أن ما كنت أقول لهم حق. وقال قتادة: أحياهم الله له حتى سمعوا مقالته تقريعًا وتوبيخًا ونقمة. والصحيح عند العلماء رواية ابن عمر؛ لما لها من الشواهد على صحتها من وجوه كثيرة، من أشهر ذلك ما رواه ابن عبد البر مصحِّحًا له، عن ابن عباس مرفوعًا: «ما من أحد يمر بقبر أخيه المسلم، كان يعرفه في الدنيا، فيسلم عليه، إلا رد الله عليه روحه، حتى يرد عليه السلام». وثبت عنه صلى الله عليه وسلم أن الميت يسمع قرع نعال المشيعين له إذا انصرفوا عنه، وقد شرع النبي صلى الله عليه وسلم لأمته إذا سلموا على أهل القبور أن يسلموا عليهم سلام مَن يخاطبونه فيقول المسلم: السلام عليكم دار قوم مؤمنين. وهذا خطاب لِمَن يسمع ويعقل، ولولا هذا الخطاب لكانوا بمنزلة خطاب المعدوم والجماد، والسلف مجمعون على هذا، وقد تواترت الآثارُ عنهم بأنّ الميت يعرف بزيارة الحي له ويستبشر».", "mawaqif": [{"taliq": 5121, "mi": 0, "aya": 52, "alam": "ابن تيمية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 189", "qawl": "", "nass": "وعائشة تأولت فيما ذكرته كما تأولت أمثال ذلك. والنص الصحيح عن النبي صلى الله عليه وسلم، مقدم على تأويل من تأول من أصحابه وغيره، وليس في القرآن ما ينفي ذلك؛ فإن قوله: {إنك لا تسمع الموتى} إنما أراد به السماع المعتاد الذي ينفع صاحبه، فإن هذا مثل ضرب للكفار، والكفار تسمع الصوت، لكن لا تسمع سماع قبول بفقه واتباع، كما قال تعالى: {ومثل الذين كفروا كمثل الذي ينعق بما لا يسمع إلا دعاء ونداء} [البقرة: 171]", "qawaid": [], "tabi": ""}, {"taliq": 5121, "mi": 0, "aya": 52, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "11/ 39 - 40", "qawl": "", "nass": "وقد استدلت أم المؤمنين عائشة رضي الله عنها- بهذه الآية: {إنك لا تسمع الموتى} على توهيم عبد الله بن عمر في روايته مخاطبة النبي صلى الله عليه وسلم القتلى الذين ألقوا في القليب قليب بدر بعد ثلاثة أيام، ومعاتبته إياهم، وتقريعه لهم، حتى قال له عمر: يا رسول الله، ما تخاطب من قوم قد جيفوا؟ فقال: «والذي نفسي بيده، ما أنتم بأسمع لما أقول منهم، ولكن لا يجيبون", "qawaid": [], "tabi": ""}]}, {"id": 5122, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (18/ 524) غير قول قتادة.", "mawaqif": []}], "54": [{"id": 5123, "kinds": "ترجيح،نقل", "text": "رجّح ابنُ عطية (7/ 36) الضم في قوله: {ضعف}، فقال عقب ذكره القراءتين: «والضم أصوب». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 5123, "mi": 0, "aya": 54, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 36", "qawl": "", "nass": "والضم أصوب", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}], "55": [{"id": 5124, "kinds": "نقد", "text": "انتقد ابنُ عطية (7/ 37) مستندًا إلى السياق ما جاء في قول يحيى بن سلام وغيره، فقال: «وقيل: المعنى: ما لبثوا في الدنيا، كأنهم استَقَلُّوها لمّا عاينوا أمر الآخرة. وهذا يُضْعِفه قوله تعالى: {كَذلِكَ كانُوا يُؤْفَكُونَ}؛ إذ لو أرادوا تقليل الدنيا بالإضافة إلى الآخرة لكان منزعًا شديدًا، وكان قولهم: {غير ساعَةٍ} تجوُّزًا في القدر والموازنة».", "mawaqif": [{"taliq": 5124, "mi": 0, "aya": 55, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 37", "qawl": "يحيى بن", "nass": "وقيل: المعنى: ما لبثوا في الدنيا، كأنهم استقلوها لما عاينوا أمر الآخرة. وهذا يضعفه قوله تعالى: {كذلك كانوا يؤفكون}؛ إذ لو أرادوا تقليل الدنيا بالإضافة إلى الآخرة لكان منزعا شديدا، وكان قولهم: {غير ساعة} تجوزا في القدر والموازنة", "qawaid": ["السياق"], "tabi": ""}]}], "56": [{"id": 5125, "kinds": "نقل", "text": "قال ابنُ عطية (7/ 37): «وقال بعض المفسرين: إنما أراد: أوتوا الإيمان والعلم؛ ففي الكلام تقديم وتأخير. [كما في رواية ابن جرير لقول قتادة]. ولا يُحتاج إلى هذا، بل ذكر العلم يتضمن الإيمان، ولا يصف الله بعلم من لم يعلم كل ما يوجب الإيمان، ثم ذكر الإيمان بعد ذلك تنبيهًا عليه وتشريفًا لأمره كما قال تعالى: {فاكِهَةٌ ونَخْلٌ ورُمّانٌ} [الرحمن: 68]، فنبَّه على مكان الإيمان، وخصَّه بالذِّكر تشريفًا».", "mawaqif": [{"taliq": 5125, "mi": 0, "aya": 56, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 37", "qawl": "", "nass": "وقال بعض المفسرين: إنما أراد: أوتوا الإيمان والعلم؛ ففي الكلام تقديم وتأخير. [كما في رواية ابن جرير لقول قتادة]. ولا يحتاج إلى هذا، بل ذكر العلم يتضمن الإيمان، ولا يصف الله بعلم من لم يعلم كل ما يوجب الإيمان، ثم ذكر الإيمان بعد ذلك تنبيها عليه وتشريفا لأمره كما قال تعالى: {فاكهة ونخل ورمان} [الرحمن: 68]، فنبه على مكان الإيمان، وخصه بالذكر تشريفا", "qawaid": [], "tabi": ""}]}]}, "athar": {"60546": {"num": 60546, "aya": 27, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {وهُوَ أهْون عَلَيْهِ}، قال: الإعادةُ أهونُ عليه مِن البداءة، والبداءة عليه هيِّنٌ."}, "60674": {"num": 60674, "aya": 39, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- {وما آتَيْتُمْ مِن رِبًا لِيَرْبُوَ فِي أمْوالِ النّاسِ}، قال: ما أعطيت مِن شيء تريد مثابة الدنيا ومجازاة الناس؛ ذاك الربا الذي لا يقبله الله، ولا يجزي به."}, "60678": {"num": 60678, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق قتادة- في قوله: {وما آتَيْتُمْ مِن زَكاةٍ}، قال: هي الصدقة."}, "60551": {"num": 60551, "aya": 27, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {وهُوَ أهْون عَلَيْهِ}، يقول: إعادته أهونُ عليه من بدئه، وكلٌّ على الله هيِّن."}, "60679": {"num": 60679, "aya": 39, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبى نجيح- قوله: {وما آتَيْتُمْ مِن زَكاةٍ}، قال: هي الصدقة."}, "60680": {"num": 60680, "aya": 39, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {وما آتَيْتُمْ مِن زَكاةٍ تُرِيدُونَ وجْهَ اللَّهِ فَأُولَئِكَ هُمُ المُضْعِفُونَ}، قال: هذا الذي يقبله الله، ويضعفه لهم عشر أمثالها وأكثر من ذلك."}, "60556": {"num": 60556, "aya": 27, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق ابن أبي طلحة- في قوله: {وله المثل الأَعْلى}، يقول: ليس كمثله شيء."}, "60557": {"num": 60557, "aya": 27, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {وله المثل الأَعْلى}، قال: شهادة أن لا إله إلا الله."}, "60558": {"num": 60558, "aya": 27, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وله المثل الأَعْلى}، قال: مثله أنه لا إله إلا هو، ولا معبود غيره."}, "60560": {"num": 60560, "aya": 28, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- قال: كان يُلَبِّي أهلُ الشرك: لبيك اللهم لبيك، لبيك لا شريك لك، إلا شريكًا هو لك، تملكُه وما ملَك. فأنزل الله: {هَلْ لَكُمْ مِن ما مَلَكَتْ أيْمانُكُمْ مِن شُرَكاءَ}."}, "60562": {"num": 60562, "aya": 28, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطاء الخراساني- في قوله: {هَلْ لَكُمْ مِن ما مَلَكَتْ أيْمانُكُمْ}، قال: هي في الآلهة، وفيه يقول: تخافونهم أن يرِثوكم كما يَرِث بعضُكم بعضًا."}, "60692": {"num": 60692, "aya": 41, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {ظَهَرَ الفَسادُ فِي البَرِّ والبَحْر}، قال: في البر: ابن آدم الذي قتل أخاه. وفي البحر: الذي كان يأخذ كل سفينة غصبًا."}, "60693": {"num": 60693, "aya": 41, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق النضر بن عربي- {وإذا تَوَلّى سَعى فِي الأَرْضِ لِيُفْسِدَ فِيها} [البقرة: 205]، قال: إذا ولي سعى بالعداء والظلم، فيحبس الله القطر، فيهلك الحرث والنسل، {واللَّهُ لا يُحِبُّ الفَسادَ}. ثم قرأ مجاهد: {ظَهَرَ الفَسادُ فِي البَرِّ والبَحْرِ}، ثم قال: أما واللهِ، ما هو بَحْركم هذا، ولكن كل قرية على ماءٍ جارٍ فهو بحر."}, "60701": {"num": 60701, "aya": 41, "qail": "عطية بن سعد العوفي", "tabaqa": "تابعي", "bab": "", "text": "قال عطية بن سعد العوفي: {ظَهَرَ الفَسادُ فِي البَرِّ والبَحْرِ}، البر: ظهر الأرض؛ الأمصار وغيرها. والبحر: هو البحر المعروف."}, "60702": {"num": 60702, "aya": 41, "qail": "عطية بن سعد العوفي", "tabaqa": "تابعي", "bab": "", "text": "عن عطية بن سعد العوفي -من طريق فضيل بن مرزوق- أنّه قيل له: {ظَهَرَ الفَسادُ فِي البَرِّ والبَحْرِ} هذا البر، والبحر أيُّ فساد فيه؟ قال: إذا قلَّ المطرُ قلَّ الغوص."}, "60449": {"num": 60449, "aya": 15, "qail": "يحيى بن أبي كثير", "tabaqa": "تابعي", "bab": "", "text": "عن يحيى بن أبي كثير، في قوله: {يحبرون}، قيل: يا رسول الله، ما الَحبْرُ؟ قال: «اللذَّة، والسماع». (11 / -588)"}, "60450": {"num": 60450, "aya": 15, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عَبّاس -من طريق علي بن أبي طلحة- في قوله: {يُحْبَرُونَ}، قال: يُكرَمون."}, "60451": {"num": 60451, "aya": 15, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {يُحْبَرُونَ}، قال: يُنَعَّمون."}, "60455": {"num": 60455, "aya": 15, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة -من طريق سعيد- {فِي رَوْضَة يُحْبَرُونَ}: يُنَعَّمُون."}, "60456": {"num": 60456, "aya": 15, "qail": "يحيى بن أبي كثير", "tabaqa": "تابعي", "bab": "", "text": "عن يحيى بن أبي كثير -من طريق الأوزاعي- {فِي رَوْضَة يُحْبَرُونَ}، قال: لذّة السماع في الجنَّة."}, "60466": {"num": 60466, "aya": 15, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: في الجنة شجرةٌ على ساقٍ، قدر ما يسير الراكب المُجِدُّ في ظِلِّها مائةَ عام، فيخرج أهل الجنة أهل الغرف وغيرهم، فيتحدثون في ظلها، فيشتهي بعضُهم، ويذكر لهو الدنيا، فيرسل اللهُ رِيحًا من الجنة، فتحرك تلك الشجرة بكل لهوٍ كان في الدنيا."}, "60468": {"num": 60468, "aya": 15, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن مجاهد بن جبر -من طريق علي بن أبي الوليد- أنه سئل: هل في الجنة سماع؟ فقال: إنّ فيها لَشجرة يُقال لها: القيض، لها سماع لم يسمع السامعون إلى مثله."}, "60469": {"num": 60469, "aya": 15, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن مجاهد بن جبر، قال: يُنادي منادٍ يوم القيامة: أين الذين كانوا يُنَزِّهون أصواتهم وأسماعهم عن اللهو ومزامير الشيطان؟ فيحملهم اللهُ في رياض الجنة مِن مسك، فيقول للملائكة: أسمِعُوا عبادي تحميدي وتمجيدي، وأخبروهم: أن لا خوف عليهم، ولا هم يحزنون."}, "60663": {"num": 60663, "aya": 39, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق الحارث وورقاء، عن ابن أبي نجيح- في قوله: {وما آتَيْتُمْ مِن رِبًا لِيَرْبُوَ فِي أمْوالِ النّاسِ فَلا يَرْبُو عِنْدَ اللَّهِ}، قال: يعطي مالَه يبتغي أفضل منه."}, "60666": {"num": 60666, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عمر بن عطاء-، مثله."}, "60670": {"num": 60670, "aya": 39, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "قال عامر الشعبي -من طريق زكريا- {وما آتَيْتُمْ مِن رِبًا لِيَرْبُوَ فِي أمْوالِ النّاسِ}، قال: هو الرجل يلتزق بالرجل، فيخف له ويخدمه، ويسافر معه، فيحمل له ربحَ بعض ماله؛ ليجزيه، وإنما أعطاه التماس عونه، ولم يُرِد وجْهَ الله."}, "60385": {"num": 60385, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- {يَعْلَمُونَ ظاهِرًا مِنَ الحَياةِ الدُّنْيا}: يعني: معايشهم؛ متى يغرسون، ومتى يزرعون، ومتى يحصدون."}, "60386": {"num": 60386, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق ابن أبي طلحة- {يَعْلَمُونَ ظاهِرًا مِنَ الحَياةِ الدُّنْيا}: يعني: الكفار، يعرفون عمران الدنيا، وهم في أمر الآخرة جُهّال."}, "60387": {"num": 60387, "aya": 7, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرياحي -من طريق الربيع- قال: صرفَها في معيشتها."}, "60389": {"num": 60389, "aya": 7, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق منصور- {يَعْلَمُونَ ظاهِرًا مِنَ الحَياةِ الدُّنْيا}، قال: اليهود والنصارى والمشركون يعلمون ما يرفق بهم وينفعهم في معايشهم في الدنيا، وهم عن الآخرة هم غافلون."}, "60390": {"num": 60390, "aya": 7, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق منصور- {يَعْلَمُونَ ظاهِرًا مِنَ الحَياةِ الدُّنْيا}، قال: معايشهم، وما يُصلِحهم."}, "60395": {"num": 60395, "aya": 7, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {يَعْلَمُونَ ظاهِرًا مِنَ الحَياةِ الدُّنْيا}: يعلمون تجارتها، وحِرفتها، وبيعها."}, "60651": {"num": 60651, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عباس -من طريق عبد الرحمن الأعرج- أنه قرأها: «لِتُرْبُواْ»."}, "60653": {"num": 60653, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق أبى حصين- {وما آتَيْتُمْ مِن رِبًا لِيَرْبُوَ فِي أمْوالِ النّاسِ}، قال: ألم تر إلى الرجل يقول للرجل: لأُمَوِّلَنَّك. فيعطيه، فهذا لا يربو عند الله؛ لأنه يعطيه لغير الله ليثري ماله."}, "60654": {"num": 60654, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، في قوله: {وما آتَيْتُمْ مِن رِبًا}، قال: الربا رباءان؛ ربًا لا بأس به، وربًا لا يصلح، فأمّا الربا الذي لا بأس به فهدية الرجل إلى الرجل يريد فضلها، وأضعافها."}, "60655": {"num": 60655, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- {وما آتَيْتُمْ مِن رِبًا}، قال: هو ما يعطي الناس بينهم بعضهم بعضًا، يعطي الرجلُ الرجلَ العطية يريد أن يُعطى أكثر منها."}, "60656": {"num": 60656, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق قتادة- في قوله: {وما آتَيْتُمْ مِن رِبًا لِيَرْبُوَ فِي أمْوالِ النّاسِ}: هي هدية الرجل، يهدي الشيءَ يريد أن يُثاب بأفضل منه، فذلك الذي لا يربو عند الله، لا يؤجر فيه صاحبه، ولا إثم عليه."}, "60657": {"num": 60657, "aya": 39, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح-، مثله."}, "60658": {"num": 60658, "aya": 39, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن جبير -من طريق منصور بن صفية- {وما آتَيْتُمْ مِن رِبًا لِيَرْبُوَ فِي أمْوالِ النّاسِ فَلا يَرْبُو عِنْدَ اللَّهِ}، قال: ما أعطيتم مِن عَطِيَّة لِتُثابوا عليها في الدنيا؛ فليس فيها أجر."}, "60659": {"num": 60659, "aya": 39, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إبراهيم النخعي -من طريق ابن فُضيل، عن ابن أبي خالد- قال: {وما آتَيْتُمْ مِن رِبًا لِيَرْبُوَ فِي أمْوالِ النّاسِ فَلا يَرْبُو عِنْدَ اللَّهِ} هو الرجل يُهدي إلى الرجل الهدية لِيُثِيبَه أفضلَ منها."}, "60660": {"num": 60660, "aya": 39, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إبراهيم النخعي -من طريق مروان بن معاوية، عن إسماعيل بن أبي خالد- قال: {وما آتَيْتُمْ مِن رِبًا لِيَرْبُوَ فِي أمْوالِ النّاسِ فَلا يَرْبُو عِنْدَ اللَّهِ}، كان هذا في الجاهلية، يُعطِي أحدُهم ذا القرابةِ المالَ؛ يكثر به ماله."}, "60661": {"num": 60661, "aya": 39, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إبراهيم النخعي -من طريق سفيان، عن إسماعيل بن أبي خالد- قوله: {وما ءاتيتم من ربا ليربوا في أموال الناس فلا يربوا عند الله}، قال: هو الرجل يكون له ابنُ عمٍّ، فيكون فقيرًا، فيعطيه لكيما لا يرى لابن عمِّه خَصاصة."}, "60534": {"num": 60534, "aya": 26, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {كُلٌّ لَهُ قانِتُونَ}: أي: مطيع مُقِرٌّ بأن الله ربه وخالقه."}, "60662": {"num": 60662, "aya": 39, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق سفيان، عن ابن أبي نجيح- في قوله: {وما آتَيْتُمْ مِن رِبًا لِيَرْبُوَ فِي أمْوالِ النّاسِ فَلا يَرْبُو عِنْدَ اللَّهِ}، قال: هي الهدايا."}, "60664": {"num": 60664, "aya": 39, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "قال مجاهد بن جبر -من طريق ورقاء، عن ابن أبي نجيح-: {فَلا يَرْبُو عِنْدَ اللَّهِ} مَن أعطى عَطِيَّةً يبتغي أفضل منه فلا أجر له فيها."}, "60665": {"num": 60665, "aya": 39, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مزاحم -من طريق عبيد- في قوله: {وما آتَيْتُمْ مِن رِبًا} الآية، قال: هو الربا الحلال؛ أن تُهْدِي تُريد أكثرَ منه، وليس له أجر ولا وزر، ونُهِي عنه النبي صلى الله عليه وسلم خاصة، فقال: {ولا تَمْنُنْ تَسْتَكْثِرُ} [المدثر: 6]."}, "60538": {"num": 60538, "aya": 26, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {كُلٌّ لَهُ قانِتُونَ}، قال: كل له مطيعون. المطيع: القانت. قال: وليس شيء إلا وهو مطيع، إلا ابن آدم، وكان أحقهم أن يكون أطوعهم لله. وفي قوله: {وقُومُوا لِلَّهِ قانِتِينَ} [البقرة: 238]، قال: هذا في الصلاة، لا تتكلموا في الصلاة كما يتكلم أهل الكتاب في الصلاة. قال: وأهلُ الكتاب يمشي بعضُهم إلى بعض في الصلاة. قال: ويتقاتلون في الصلاة، فإذا قيل لهم في ذلك، قالوا: لكي تذهب الشحناء مِن قلوبنا، وتسلم قلوب بعضنا لبعض، فقال الله: {وقُومُوا لِلَّهِ قانِتِينَ} لا تزولوا كما يزولون، {قانِتِينَ} لا تتكلموا كما يتكلمون. قال: فأما ما سوى هذا كله في القرآن من القنوت فهو الطاعة، إلا هذه الواحدة."}, "60667": {"num": 60667, "aya": 39, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مزاحم -من طريق عبيد- في قوله: {وما آتَيْتُمْ مِن رِبًا لِيَرْبُوَ فِي أمْوالِ النّاسِ}: فهو ما يتعاطى الناس بينهم ويتهادون؛ يعطي الرجلُ العطيةَ ليصيبَ منه أفضل منها. وأما قوله: {ولا تَمْنُنْ تَسْتَكْثِرُ} [المدثر: 6] فهذا للنبي خاصة، لم يكن له أن يعطي إلا لله، ولم يكن يعطي ليعطى أكثر منه."}, "60668": {"num": 60668, "aya": 39, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مزاحم -من طريق ابن أبي روّاد- في قوله: {وما آتَيْتُمْ مِن رِبًا لِيَرْبُوَ فِي أمْوالِ النّاسِ}، قال: هذا للنبي صلى الله عليه وسلم، هذا الربا الحلال."}, "60541": {"num": 60541, "aya": 27, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق ابن أبي طلحة- {وهُوَ أهْون عَلَيْهِ}، قال: أيْسَرُ."}, "60542": {"num": 60542, "aya": 27, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، في قوله: {وهُوَ أهْون عَلَيْهِ}، قال: الإعادةُ أهون على المخلوق؛ لأنه يقول له يوم القيامة: كن. فيكون، وابتداء الخلقة مِن نطفة ثم مِن علقة ثم مِن مضغة."}, "60543": {"num": 60543, "aya": 27, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق الكلبي عن أبي صالح- {وهُوَ أهْون عَلَيْهِ}: أي: على الخلق، يقومون بصيحة واحدة، فيكون أهون عليهم من أن يكونوا نطفًا، ثم علقًا، ثم مضغًا، إلى أن يصيروا رجالًا ونساء."}}, "n_athar": {"0": 40, "3": 12, "4": 20, "5": 1, "6": 2, "7": 16, "8": 7, "9": 15, "10": 8, "11": 2, "12": 10, "13": 2, "14": 4, "15": 25, "16": 2, "17": 14, "19": 8, "20": 5, "21": 8, "22": 4, "23": 2, "24": 4, "25": 11, "26": 7, "27": 21, "28": 11, "29": 2, "30": 42, "31": 4, "32": 9, "33": 3, "34": 2, "35": 7, "36": 3, "37": 2, "38": 6, "39": 33, "40": 3, "41": 36, "42": 2, "43": 8, "44": 3, "45": 3, "46": 8, "47": 3, "48": 15, "49": 4, "50": 2, "51": 2, "52": 8, "53": 2, "54": 8, "55": 8, "56": 5, "57": 2, "58": 2, "59": 2, "60": 4}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});